<script setup lang="ts">import { ref,onMounted } from 'vue';import { api } from '../../api';import SourceTag from '../../components/common/SourceTag.vue';const school=ref<any>(null);const profile=ref<any>(null);const life=ref<any[]>([]);onMounted(async()=>{school.value=await api.school('demo-1');profile.value=await api.schoolProfile('demo-1');life.value=(await api.schoolLife('demo-1')).items})</script><template><section class="content-page"><div class="eyebrow">SCHOOL / PROFILE</div><h1>{{school?.name||'院校详情'}}</h1><p class="lede">{{school?.intro||'加载演示画像…'}}</p><div v-if="school" class="detail-grid"><div><b>所在省份</b><p>{{school.province}}</p></div><div><b>城市</b><p>{{school.city}}</p></div><div><b>办学类型</b><p>{{school.ownership}}</p></div></div><div v-if="profile" class="feature-card"><h2>画像摘要</h2><p>学费：{{profile.tuition_range}}；{{profile.source_note}}</p></div><div v-for="item in life" :key="item.category" class="feature-card"><h3>{{item.category}}</h3><p>{{item.content}}</p><SourceTag :type="item.source_type" :reliability="item.reliability"/></div></section></template>
